cd /app && python3 - <<'EOF'
import struct, json

d=open('trunc.db','rb').read()

def varint(buf,pos):
    v=0
    for i in range(9):
        b=buf[pos+i]
        if i==8:
            return (v<<8)|b, pos+9
        v=(v<<7)|(b&0x7f)
        if not b&0x80:
            return v,pos+i+1

def decode(payload):
    hlen,p=varint(payload,0)
    types=[]
    while p<hlen:
        t,p=varint(payload,p); types.append(t)
    vals=[]; body=hlen
    for t in types:
        if t==0: vals.append(None)
        elif t<=6:
            n=[0,1,2,3,4,6,8][t]
            vals.append(int.from_bytes(payload[body:body+n],'big',signed=True)); body+=n
        elif t==7:
            vals.append(struct.unpack('>d',payload[body:body+8])[0]); body+=8
        elif t==8: vals.append(0)
        elif t==9: vals.append(1)
        elif t>=12:
            n=(t-12)//2
            b=payload[body:body+n]; body+=n
            vals.append(b.decode('utf-8') if t&1 else b)
        else: raise ValueError(t)
    return vals

n=struct.unpack('>H',d[3:5])[0]
ptrs=[struct.unpack('>H',d[8+2*i:10+2*i])[0] for i in range(n)]
rows=[]
for ptr in ptrs:
    plen,p=varint(d,ptr)
    rowid,p=varint(d,p)
    vals=decode(d[p:p+plen])
    rows.append((rowid, vals[1], vals[2]))

rows.sort()
out=[{"word":w,"value":v} for _,w,v in rows]
with open('recover.json','w') as f:
    json.dump(out,f,indent=2)
print(json.dumps(out,indent=2))
